  internal static bool DismissFocusedPicker(DependencyObject focused){for(var item=focused;item!=null;){var dismiss=item.GetValue(PickerDismissProperty) as Func<bool>;if(dismiss!=null&&dismiss())return true;var picker=item as ComboBox;if(picker!=null&&picker.IsDropDownOpen){picker.IsDropDownOpen=false;return true;}var option=item as ComboBoxItem;if(option!=null){var owner=ItemsControl.ItemsControlFromItemContainer(option) as ComboBox;if(owner!=null&&owner.IsDropDownOpen){owner.IsDropDownOpen=false;return true;}}item=item is Visual||item is System.Windows.Media.Media3D.Visual3D?VisualTreeHelper.GetParent(item):LogicalTreeHelper.GetParent(item);}return false;}
