   var headingText=new TextBlock{FontSize=20,MaxHeight=84,TextTrimming=TextTrimming.CharacterEllipsis,TextWrapping=TextWrapping.Wrap,Margin=new Thickness(0,0,8,0),Foreground=Foreground,VerticalAlignment=VerticalAlignment.Center};headingText.SetBinding(TextBlock.TextProperty,new System.Windows.Data.Binding("Title"){Source=this});headingText.SetBinding(FrameworkElement.ToolTipProperty,new System.Windows.Data.Binding("Title"){Source=this});heading.Children.Add(headingText);
   var close=new Button{Name="dialogClose",Content="×",Width=38,Height=38,Padding=new Thickness(0),FontSize=22,VerticalAlignment=VerticalAlignment.Top};System.Windows.Automation.AutomationProperties.SetName(close,"Закрыть диалог");close.ToolTip="Закрыть";close.Click+=(s,e)=>Close();Grid.SetColumn(close,1);WindowChrome.SetIsHitTestVisibleInChrome(close,true);heading.Children.Add(close);DockPanel.SetDock(heading,Dock.Top);layout.Children.Add(heading);
