 public sealed partial class MainWindow {
  static WrapPanel CompactTools(params Button[] buttons){var panel=new WrapPanel{Margin=new Thickness(0,6,0,12)};foreach(var button in buttons){button.MinWidth=136;button.Margin=new Thickness(0,0,12,0);panel.Children.Add(button);}return panel;}
  static UniformGrid Toolbar(params Button[] buttons){var grid=new UniformGrid{Columns=Math.Max(1,buttons.Length),Margin=new Thickness(0,0,0,10)};foreach(var button in buttons)grid.Children.Add(button);Action layout=()=>{bool compact=grid.ActualWidth>0&&grid.ActualWidth<420;grid.Columns=compact?1:Math.Max(1,buttons.Count(b=>b.Visibility!=Visibility.Collapsed));for(int i=0;i<buttons.Length;i++)buttons[i].Margin=compact?new Thickness(0,0,0,8):new Thickness(0,0,i==buttons.Length-1?0:12,0);};foreach(var b in buttons)b.IsVisibleChanged+=(s,e)=>layout();grid.SizeChanged+=(s,e)=>layout();layout();return grid;}
  static Grid Columns(UIElement left,UIElement right,double ratio=1){var grid=new Grid();grid.ColumnDefinitions.Add(new ColumnDefinition{Width=new GridLength(ratio,GridUnitType.Star)});grid.ColumnDefinitions.Add(new ColumnDefinition{Width=new GridLength(16)});grid.ColumnDefinitions.Add(new ColumnDefinition());grid.Children.Add(left);Grid.SetColumn(right,2);grid.Children.Add(right);return grid;}
  static StackPanel Field(string label,UIElement control){var panel=new StackPanel();panel.Children.Add(Text(label));panel.Children.Add(control);return panel;}
  static DataGridTemplateColumn CellColumn(string heading,double width,Func<object,UIElement> create){var factory=new FrameworkElementFactory(typeof(CellPresenter));factory.SetValue(CellPresenter.CreateProperty,create);return new DataGridTemplateColumn{Header=heading,Width=new DataGridLength(width,DataGridLengthUnitType.Star),CellTemplate=new DataTemplate{VisualTree=factory},CanUserSort=false};}
  Button ServicePicker(CheckBox[] checks,string caption="Сервисов"){
   var button=new Button{Name="servicePicker",MinWidth=140,MinHeight=38,VerticalAlignment=VerticalAlignment.Top};
   System.Windows.Automation.AutomationProperties.SetName(button,"Выбрать · "+caption);
   var list=new StackPanel{Margin=new Thickness(12)};var label=new FrameworkElementFactory(typeof(TextBlock));label.SetBinding(TextBlock.TextProperty,new Binding());label.SetValue(TextBlock.TextWrappingProperty,TextWrapping.Wrap);var labelTemplate=new DataTemplate{VisualTree=label};
   foreach(var check in checks){check.MinHeight=32;check.ContentTemplate=labelTemplate;check.ToolTip=check.Content;check.HorizontalContentAlignment=HorizontalAlignment.Stretch;list.Children.Add(check);}
   var scroller=new ScrollViewer{Content=list,MaxHeight=320,VerticalScrollBarVisibility=ScrollBarVisibility.Auto,HorizontalScrollBarVisibility=ScrollBarVisibility.Disabled};
   var surface=new Border{Name="servicePickerSurface",Background=Brush(CompactLight?"#F5F8FA":"#20262D"),CornerRadius=new CornerRadius(12),BorderBrush=Brush(CompactOutline),BorderThickness=new Thickness(1),Child=scroller};
   var popup=new Popup{PlacementTarget=button,Placement=PlacementMode.Bottom,StaysOpen=false,AllowsTransparency=true,Child=surface};
   Func<bool> dismiss=()=>{if(!popup.IsOpen)return false;popup.IsOpen=false;button.Focus();return true;};WorkspaceDialog.RegisterPickerDismiss(button,dismiss);WorkspaceDialog.RegisterPickerDismiss(list,dismiss);
   popup.Opened+=(s,e)=>{var host=Window.GetWindow(button);surface.Width=Math.Max(160,Math.Min(360,(host==null?400:host.ActualWidth)-32));ApplyCompactControlPalette(list);var first=checks.FirstOrDefault(c=>c.IsEnabled&&c.Visibility==Visibility.Visible);if(first!=null)first.Focus();};
   list.PreviewKeyDown+=(s,e)=>{if(e.Key==Key.Escape){dismiss();e.Handled=true;}};button.PreviewKeyDown+=(s,e)=>{if(e.Key==Key.Escape&&dismiss())e.Handled=true;};
   Action refresh=()=>button.Content=caption+": "+checks.Count(c=>c.IsChecked==true);foreach(var check in checks){check.Checked+=(s,e)=>refresh();check.Unchecked+=(s,e)=>refresh();}button.Click+=(s,e)=>popup.IsOpen=!popup.IsOpen;button.Unloaded+=(s,e)=>popup.IsOpen=false;refresh();return button;
  }
  void Notice(string message,string heading="MCRF"){var window=Dialog(heading,660,300);window.MaxHeight=window.Height;window.SizeToContent=SizeToContent.Height;var panel=new DockPanel{Margin=new Thickness(24)};var ok=Button("Понятно",()=>window.DialogResult=true);ok.IsDefault=true;ok.IsCancel=true;ok.Name="sharedNoticeAccept";ok.HorizontalAlignment=HorizontalAlignment.Right;ok.MinWidth=150;DockPanel.SetDock(ok,Dock.Bottom);panel.Children.Add(ok);panel.Children.Add(new ScrollViewer{Content=Text(message),VerticalScrollBarVisibility=ScrollBarVisibility.Auto});window.Content=panel;window.ShowDialog();}
